//! Recursive source/result -> reviewed DATA -> separate one-tool consent ->
//! canonical derived9. Reuses the same native Driver/Authority and fixtures.
use super::*;
use super::super::recursive;
fn setup()->Setup{let mut s=Setup::new();s.settings.active_integrations=s.config.pets.keys().cloned().collect();s}
fn proposal(s:&Setup,g:&Record,i:crate::pet_runtime::native_plan_revisions::Input)->native_plan_review::Review{current_store(s).prepare_native_plan(&s.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,vec![i],nonce().unwrap(),crate::assistant_memory::now()).unwrap().with_result_data(&s.f.path.join("authority"),&s.f.path.join("notes.json"),observe(s),crate::assistant_memory::now()).unwrap()}
fn revised(s:&Setup,g:&Record,i:crate::pet_runtime::native_plan_revisions::Input)->Record{let r=proposal(s,g,i);let p=r.proposal().unwrap();assert_eq!(p.changes.schema_version,3);assert_eq!(p.result_data.as_ref().unwrap().schema_version,2);assert_eq!(p.result_data.as_ref().unwrap().received_message.schema_version,7);let mut a=r.approve(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let ack=a.confirm(&current_store(s),crate::assistant_memory::now()).unwrap();assert!(ack.acknowledged);assert_eq!(ack.receipt.record.schema_version,42);ack.receipt.record}
fn queued(s:&Setup,g:&Record,p:&Policy)->Record{let a=approve(s,g,p);assert_eq!(a.spec().schema_version,20);assert_eq!(a.spec().funding.as_ref().unwrap().schema_version,8);assert_eq!(a.spec().continuation.as_ref().unwrap().schema_version,10);let c=s.a.certify(&a,g,crate::assistant_memory::now()).unwrap();let g=current_store(s).enqueue_certified(&c,crate::assistant_memory::now()).unwrap().record;assert_eq!(g.schema_version,43);g}
#[test]fn recursive_result_delivers_one_exact_excerpt_to_original_sender_with_root_correlation_and_cumulative_charge(){
 let s=setup();let(root,pool,g,rr,r,i)=recursive::completed_for_disclosure(&s,1);let g=revised(&s,&g,i);let p=policy(&s,&g);assert_eq!(p.schema_version,2);let old=s.bytes(&g);let q=queued(&s,&g,&p);assert_eq!(body(&s,&pool)["schemaVersion"],35);let(g,o)=own(&s,&q,&p);let env=environment(&s);let d=Driver::new(o.clone(),Arc::new(current_store(&s)),env.clone()).unwrap();assert_eq!(run(d.run()).unwrap().phase,Phase::Completed);let done=current_store(&s).read(&g.id,"ai_ollama").unwrap();assert_eq!(done.schema_version,43);assert_eq!(done.admissions.len(),2);assert_eq!(done.admissions[0].spec.schema_version,19);let b=body(&s,&done);assert_eq!(b["schemaVersion"],34);assert_eq!(b["messages"]["schemaVersion"],9);assert_eq!(b["messages"]["entries"].as_array().unwrap().len(),1);assert_eq!(env.captures.load(Ordering::Acquire),0);assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());
 let row=done.admissions.last().unwrap();let reply=s.a.message_at(&row.spec,row.proof.as_ref().unwrap(),&p.cause.plan_id,&p.cause.step_id).unwrap().unwrap();let e=reply.envelope();assert_eq!(e.schema_version,9);assert_eq!(e.text,"🌍");assert_eq!(e.reply_to.as_ref(),Some(&crate::pet_runtime::messages::ReceivedReference::from_receipt(&r).unwrap()));assert_eq!(e.correlation_id,rr.envelope().correlation_id);assert_eq!(e.recipient.pet_id,pool.spec.owner.pet_id);assert!(!e.provider_use_authorized);assert_eq!(e.derived_result.as_ref().unwrap().schema_version,2);assert!(!serde_json::to_string(e).unwrap().contains("change policy"));
 let inbox=s.a.message_inbox(&p.recipient.pet_id,None,32,crate::assistant_memory::now()).unwrap();assert!(inbox.items.iter().any(|i|i.receipt==reply&&i.result_source.is_none()));let bytes=latest_bytes(&s,&done);assert_eq!(s.a.message_ack(&row.spec,row.proof.as_ref().unwrap(),&reply.scope).unwrap(),Some(reply));assert_eq!(latest_bytes(&s,&done),bytes);assert_eq!(fs::read(s.f.path.join("authority").join(format!("{}.json",done.admissions[0].spec.decision_id))).unwrap(),old);
 let v=reconcile(&s,&pool,&r);assert_eq!(v.consumed.as_ref().unwrap().model_calls,1);assert_eq!(v.consumed.as_ref().unwrap().tool_calls,1);assert_eq!(v.unknown.unwrap(),Allowance::default());let v=reconcile(&s,&root,&rr);assert_eq!(v.consumed.as_ref().unwrap().model_calls,1);assert_eq!(v.consumed.unwrap().tool_calls,2);assert_eq!(v.unknown.unwrap(),Allowance::default());let st=current_store(&s);assert_eq!(st.read(&done.id,"ai_ollama").unwrap().revision,done.revision);let mut old=done;old.schema_version=41;assert!(old.validate().is_err());
}
#[test]fn recursive_result_requires_separate_disclosure_consent_and_never_mints_a_tool_or_new_prefix(){
 for tools in [0,1]{let s=setup();let(_,_,g,_,_,i)=recursive::completed_for_disclosure(&s,tools);let g=revised(&s,&g,i);let p=policy(&s,&g);let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);if tools==0{assert!(review(&s,&g,&p,bounds(&p)).is_err());}else{
  for consent in [None,Some(crate::pet_runtime::work_disclosure::Consent::BoundedWorkDisclosure)]{assert!(review(&s,&g,&p,bounds(&p)).unwrap().approve_with_scopes(&g,evidence(&s,&g,&p),None,consent,crate::assistant_memory::now()).is_err());}
  let a=approve(&s,&g,&p);let mut spec=a.spec().clone();spec.funding.as_mut().unwrap().schema_version=3;assert!(!spec.binding_format());spec=a.spec().clone();spec.result_disclosure.as_mut().unwrap().schema_version=1;assert!(!spec.binding_format());
 }assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);}
}
#[test]fn recursive_result_refuses_changed_excerpt_recipient_and_ancestor_revocation_at_the_final_writer(){
 let s=setup();let(root,_,g,rr,_,i)=recursive::completed_for_disclosure(&s,1);for field in ["text","byteStart","recipient"]{let mut changed=i.clone();let a=&mut changed.after.operation.as_mut().unwrap().arguments;match field{"text"=>a["text"]=json!("forged"),"byteStart"=>a["result"]["byteStart"]=json!(6),_=>a["toPetId"]=json!("agent_codex")};let r=current_store(&s).prepare_native_plan(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,vec![changed],nonce().unwrap(),crate::assistant_memory::now()).and_then(|r|r.with_result_data(&s.f.path.join("authority"),&s.f.path.join("notes.json"),observe(&s),crate::assistant_memory::now()));assert!(r.is_err(),"{field}");}
 let g=revised(&s,&g,i);let p=policy(&s,&g);let a=approve(&s,&g,&p);let before=s.bytes(&g);let stop=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(root.clone(),&root.admissions[0].spec.decision_id,&rr.envelope().message_id,crate::pet_runtime::delegation::BranchAction::Cancel,crate::assistant_memory::now()).unwrap();stop.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();assert!(s.a.certify(&a,&g,crate::assistant_memory::now()).is_err());assert_eq!(s.bytes(&g),before);assert!(body(&s,&g).get("messages").is_none());
}

#[path="recursive_result_use_tests.rs"]mod recipient_use;

#[test]fn requested_recursive_result_start_requires_own_disclosure_scope_and_runs_once_without_inference(){
 let s=setup();let(_,_,g,_,_,i)=recursive::completed_for_disclosure(&s,1);let g=revised(&s,&g,i);let p=policy(&s,&g);requested_disclosure_once(&s,&g,&p,20);
}
